/*
  Public template configuration.

  Replace these placeholders after importing
  the workflow into your n8n instance.
*/

return [{
  json: {
    spreadsheet_id:
      'YOUR_GOOGLE_SHEET_ID',

    cv_active_folder_id:
      'YOUR_CV_ACTIVE_FOLDER_ID'
  }
}];

const response =
  $json ?? {};


const valueRanges =
  Array.isArray(
    response.valueRanges
  )
    ? response.valueRanges
    : [];


const jobs = [];


// --------------------------------------------------
// SCAN ALL MONTHLY SHEETS
// --------------------------------------------------

for (
  const range
  of valueRanges
) {
  const rangeName =
    String(
      range.range ?? ''
    );


  /*
    Extract the sheet name from ranges such as:

    JANEIRO!A1:Y1000
    'MARÇO'!A1:Y1000
  */
  const sheetMatch =
    rangeName.match(
      /^'?([^'!]+)'?!/
    );


  const targetSheet =
    sheetMatch
      ? sheetMatch[1]
      : '';


  const rows =
    Array.isArray(
      range.values
    )
      ? range.values
      : [];


  /*
    Row 1 contains the spreadsheet header.

    Start at index 1 so only job rows are processed.
  */
  for (
    let i = 1;
    i < rows.length;
    i++
  ) {
    const row =
      rows[i] ?? [];


    const qualified =
      String(
        row[19] ?? ''
      ).trim();


    const coverLetter =
      String(
        row[20] ?? ''
      ).trim();


    const description =
      String(
        row[11] ?? ''
      ).trim();


    /*
      A job is eligible for Workflow 03 only when:

      1. Qualified = Yeap
      2. Cover Letter is still empty
      3. Description is available
    */
    const isQualified =
      qualified
        .toLowerCase() ===
      'yeap';


    const hasNoCoverLetter =
      coverLetter === '';


    const hasDescription =
      description !== '';


    if (!isQualified) {
      continue;
    }


    if (!hasNoCoverLetter) {
      continue;
    }


    if (!hasDescription) {
      continue;
    }


    jobs.push({
      json: {

        /*
          Internal routing metadata used later to
          update the exact spreadsheet cell.
        */
        target_sheet:
          targetSheet,

        row_number:
          i + 1,


        // A - Job ID
        job_id:
          String(
            row[0] ?? ''
          ),

        // B - Status
        status:
          String(
            row[1] ?? ''
          ),

        // C - Date Scraped
        date_scraped:
          String(
            row[2] ?? ''
          ),

        // D - Source
        source:
          String(
            row[3] ?? ''
          ),

        // E - Search Keyword
        search_keyword:
          String(
            row[4] ?? ''
          ),

        // F - Date Posted
        date_posted:
          String(
            row[5] ?? ''
          ),

        // G - Title
        title:
          String(
            row[6] ?? ''
          ),

        // H - Work Mode
        work_mode:
          String(
            row[7] ?? ''
          ),

        // I - URL
        url:
          String(
            row[8] ?? ''
          ),

        // J - Company Name
        company_name:
          String(
            row[9] ?? ''
          ),

        // K - Location
        location:
          String(
            row[10] ?? ''
          ),

        // L - Description
        description,

        // M - Language
        language:
          String(
            row[12] ?? ''
          ),

        // N - Payment
        payment:
          String(
            row[13] ?? ''
          ),

        // O - Time Type
        time_type:
          String(
            row[14] ?? ''
          ),

        // P - Job Type
        job_type:
          String(
            row[15] ?? ''
          ),

        // Q - Experience
        experience:
          String(
            row[16] ?? ''
          ),

        // R - Salary
        salary:
          String(
            row[17] ?? ''
          ),

        // S - Match
        match:
          String(
            row[18] ?? ''
          ),

        // T - Qualified
        qualified,

        // U - Cover Letter
        cover_letter:
          coverLetter,

        // V - Notes
        notes:
          String(
            row[21] ?? ''
          ),

        // W - Interview At
        interview_at:
          String(
            row[22] ?? ''
          ),

        // X - Invite Meet
        invite_meet:
          String(
            row[23] ?? ''
          ),

        // Y - Attended
        attended:
          row[24] === true ||
          String(
            row[24] ?? ''
          ).toLowerCase() ===
            'true'
      }
    });
  }
}


return jobs;

const cvSource = $json ?? {};

const cvText = String(
  cvSource.text ??
  cvSource.content ??
  cvSource.data ??
  cvSource.extractedText ??
  ''
)
  .replace(/\r/g, '')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (!cvText) {
  throw new Error(
    'CV text is empty. Check the Google Drive and Extract CV Text nodes.'
  );
}

/*
  Restore all jobs previously selected by
  Filter Qualified Jobs and attach the CV text
  to each item before entering the processing loop.
*/
return $('Filter Qualified Jobs').all().map(item => ({
  json: {
    ...item.json,
    cv_text: cvText
  }
}));

