const job =
  $('Prepare Cover Letter Prompt').item.json ?? {};


/*
  Read the final recruiter message returned by
  the fact-check model.
*/
const raw =
  $json?.choices?.[0]?.message?.content ??
  $json?.text ??
  $json?.output ??
  $json?.response ??
  '';


const coverLetter =
  String(raw)
    .trim()
    .replace(
      /^```(?:text|markdown)?\s*/i,
      ''
    )
    .replace(
      /\s*```$/i,
      ''
    )
    .trim();


if (!coverLetter) {
  throw new Error(
    'Fact-check model returned an empty recruiter message.'
  );
}


/*
  Keep the job routing metadata required by the
  Google Sheets update and attach the final message.
*/
const result = {
  ...job,

  cover_letter:
    coverLetter
};


/*
  Remove temporary data that is no longer needed
  after the final message has been generated.
*/
delete result.cv_text;
delete result.cover_letter_prompt;


return {
  json: result
};

const job =
  $('Prepare Cover Letter Prompt').item.json ?? {};


const generatedMessage =
  $json?.choices?.[0]?.message?.content ??
  '';


const cvText =
  String(
    job.cv_text ?? ''
  ).trim();


const language =
  String(
    job.language ?? ''
  ).trim();


if (!generatedMessage.trim()) {
  throw new Error(
    'Generated recruiter message is empty.'
  );
}


let languageRule = '';


if (language === 'Portuguese') {
  languageRule = `
Keep the final message in natural Brazilian Portuguese.

Keep it friendly, professional and appropriate for a LinkedIn recruiter DM.
`;

} else if (language === 'English') {
  languageRule = `
Keep the final message in natural professional English.

Keep it friendly, professional and appropriate for a LinkedIn recruiter DM.
`;

} else {
  languageRule = `
Keep the same language as the original message.
`;
}


const factCheckPrompt = `
You are a strict factual editor.

Your ONLY task is to remove unsupported claims from a recruiter message.

The CANDIDATE CV below is the ONLY source of truth.


==================================================
STRICT RULES
==================================================

Review every factual statement about the candidate.

A claim may remain ONLY if it is explicitly supported by the CV.

When a specific project or experience is mentioned:

- use ONLY technologies, actions and results written inside that same project's or experience's own CV content;
- do NOT attach general skills to a specific project unless the CV explicitly does so;
- do NOT combine information from different projects or experiences;
- do NOT infer architecture, scale, purpose, implementation details or results.

Do NOT invent anything.

Do NOT add new candidate facts.

Do NOT add new technologies.

Do NOT add new achievements.

Do NOT add new explanations.

Do NOT improve the message by introducing factual details that were not already present.

Your editing strategy must be CONSERVATIVE:

1. Keep supported wording.
2. Delete unsupported words, phrases or sentences.
3. Make only minimal grammatical changes when deletion requires it.

If uncertain whether a claim is supported:
DELETE IT.


==================================================
FACTUAL CONSISTENCY
==================================================

If a technology is mentioned in the message but the CV does not explicitly
associate it with the project or experience being discussed:
remove that technology from that sentence.

If a result, responsibility or implementation detail is broader than what
the CV explicitly states:
remove or narrow the unsupported part.

If the message combines facts from different CV sections into a single
project or experience:
remove the unsupported combination.

If a claim is supported only as a general skill but not by the specific
project being discussed:
do not present it as part of that project.

Do NOT replace an unsupported fact with another invented or assumed fact.


==================================================
CV REFERENCES
==================================================

Do NOT mention the CV itself in the final message.

Never write phrases such as:

"according to my CV"
"listed in my CV"
"as stated in my CV"
"que consta no meu CV"
"que coloquei no meu CV"


==================================================
STYLE
==================================================

${languageRule}

Keep approximately the same length or shorter.

Do not turn it into a formal cover letter.

Do not add bullet points.

Do not add a subject line.

Do not add placeholders.

Keep the original conversational tone whenever possible.

Return ONLY the corrected recruiter message.


==================================================
CANDIDATE CV
SOURCE OF TRUTH
==================================================

${cvText}


==================================================
MESSAGE TO REVIEW
==================================================

${generatedMessage}
`.trim();


return {
  json: {
    ...job,

    generated_message:
      generatedMessage,

    fact_check_prompt:
      factCheckPrompt
  }
};

